    "Direct route unavailable? Here is what TravelMate builds for you:": "డైరెక్ట్ రూట్ అందుబాటులో లేదా? TravelMate మీ కోసం ఏమి నిర్మిస్తుందో ఇక్కడ ఉంది:",
    "The Multimodal Disruption & Route Recovery Engine. Navigating complex journeys with algorithmic precision.": "మల్టీమోడల్ అంతరాయం & మార్గ పునరుద్ధరణ ఇంజిన్. అల్గారిథమిక్ ఖచ్చితత్వంతో సంక్లిష్టమైన ప్రయాణాలను సులభతరం చేస్తుంది.",
    "TravelMate is an independent multimodal route discovery and recovery engine. Tickets are finalized directly on official operator portals. In an emergency, dial 112 or 139.": "TravelMate అనేది స్వతంత్ర మల్టీమోడల్ రూట్ రికవరీ ఇంజిన్. అధికారిక ఆపరేటర్ పోర్టల్‌లలో నేరుగా టిక్కెట్లు బుక్ చేయబడతాయి. అత్యవసర పరిస్థితుల్లో, 112 లేదా 139 డయల్ చేయండి.",
