    "Direct route unavailable? Here is what TravelMate builds for you:": "நேரடி பாதை இல்லையா? டிராவல்மேட் உங்களுக்காக உருவாக்குவது இதோ:",
    "The Multimodal Disruption & Route Recovery Engine. Navigating complex journeys with algorithmic precision.": "பன்முறை போக்குவரத்து சீர்குலைவு & வழித்தட மீட்பு அமைப்பு. துல்லியமான வழிமுறைகளுடன் பயணத்தை எளிதாக்குகிறது.",
    "TravelMate is an independent multimodal route discovery and recovery engine. Tickets are finalized directly on official operator portals. In an emergency, dial 112 or 139.": "டிராவல்மேட் என்பது ஒரு சுயாதீன பன்முறை வழித்தட மீட்பு அமைப்பாகும். டிக்கெட்டுகள் அதிகாரப்பூர்வ தளங்களிலேயே பதிவு செய்யப்படுகின்றன. அவசர காலங்களில் 112 அல்லது 139 ஐ அழைக்கவும்.",
