    "Direct route unavailable? Here is what TravelMate builds for you:": "ನೇರ ಮಾರ್ಗ ಲಭ್ಯವಿಲ್ಲವೇ? TravelMate ನಿಮಗಾಗಿ ಏನನ್ನು ನಿರ್ಮಿಸುತ್ತದೆ ಎಂಬುದು ಇಲ್ಲಿದೆ:",
    "The Multimodal Disruption & Route Recovery Engine. Navigating complex journeys with algorithmic precision.": "ಮಲ್ಟಿಮೋಡಲ್ ಅಡೆತಡೆ ಮತ್ತು ಮಾರ್ಗ ಮರುಪಡೆಯುವಿಕೆ ಎಂಜಿನ್. ಸಂಕೀರ್ಣ ಪ್ರಯಾಣಗಳನ್ನು ನಿಖರವಾಗಿ ನ್ಯಾವಿಗೇಟ್ ಮಾಡುವುದು.",
    "TravelMate is an independent multimodal route discovery and recovery engine. Tickets are finalized directly on official operator portals. In an emergency, dial 112 or 139.": "TravelMate ಒಂದು ಸ್ವತಂತ್ರ ಮಲ್ಟಿಮೋಡಲ್ ಮಾರ್ಗ ಮರುಪಡೆಯುವಿಕೆ ಎಂಜಿನ್ ಆಗಿದೆ. ಟಿಕೆಟ್‌ಗಳನ್ನು ಅಧಿಕೃತ ಪೋರ್ಟಲ್‌ಗಳಲ್ಲಿಯೇ ಕಾಯ್ದಿರಿಸಲಾಗುತ್ತದೆ. ತುರ್ತು ಸಂದರ್ಭದಲ್ಲಿ 112 ಅಥವಾ 139 ಗೆ ಕರೆ ಮಾಡಿ.",
    "Timetable data: Indian Railways community snapshot (circa 2016, CC0) and live provider feeds. Map data © OpenStreetMap contributors under ODbL. Weather data by Open-Meteo.": "ವೇಳಾಪಟ್ಟಿ ಡೇಟಾ: ಭಾರತೀಯ ರೈಲ್ವೆ ಸಮುದಾಯ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ ಮತ್ತು ಲೈವ್ ಫೀಡ್‌ಗಳು. ನಕ್ಷೆ ಡೇಟಾ © OpenStreetMap ಕೊಡುಗೆದಾರರು (ODbL). Open-Meteo ಹವಾಮಾನ ಡೇಟಾ.",
