    "Direct route unavailable? Here is what TravelMate builds for you:": "നേരിട്ടുള്ള റൂട്ട് ലഭ്യമല്ലേ? ട്രാവൽമേറ്റ് നിങ്ങൾക്കായി തയ്യാറാക്കുന്നത്:",
    "The Multimodal Disruption & Route Recovery Engine. Navigating complex journeys with algorithmic precision.": "മൾട്ടിമോഡൽ യാത്രാ തടസ്സ പരിഹാര എഞ്ചിൻ. സങ്കീർണ്ണമായ യാത്രകൾ അൽഗോരിതമിക് കൃത്യതയോടെ പൂർത്തിയാക്കുന്നു.",
    "TravelMate is an independent multimodal route discovery and recovery engine. Tickets are finalized directly on official operator portals. In an emergency, dial 112 or 139.": "ട്രാവൽമേറ്റ് ഒരു സ്വതന്ത്ര റൂട്ട് റിക്കവറി എഞ്ചിനാണ്. ഔദ്യോഗിക പോർട്ടലുകൾ വഴിയാണ് ടിക്കറ്റുകൾ ബുക്ക് ചെയ്യുന്നത്. അടിയന്തര ഘട്ടങ്ങളിൽ 112 അല്ലെങ്കിൽ 139 ഡയൽ ചെയ്യുക.",
