    "TravelMate is an independent multimodal route discovery and recovery engine. Tickets are finalized directly on official operator portals. In an emergency, dial 112 or 139.": "ট্র্যাভেলমেট একটি স্বাধীন মাল্টিমোডাল রুট পুনরুদ্ধার ইঞ্জিন। টিকিট সরাসরি অফিসিয়াল অপারেটর পোর্টালে চূড়ান্ত করা হয়। জরুরি অবস্থায় ১১২ বা ১৩৯ ডায়াল করুন।",
    "Timetable data: Indian Railways community snapshot (circa 2016, CC0) and live provider feeds. Map data © OpenStreetMap contributors under ODbL. Weather data by Open-Meteo.": "समय सारणी डेटा: भारतीय रेल समुदाय स्नैपशॉट (लगभग 2016, CC0) और लाइव प्रदाता फ़ीड। मानचित्र डेटा © OpenStreetMap योगदानकर्ता ODbL के तहत। ओपन-मेटियो द्वारा मौसम डेटा।",
